import { expect, test } from '@playwright/test'
import { followingMonth, localMonth } from '../../src/finance.js'

test('navigates, updates preferences and reads a salary revision across the stack', async ({ page }) => {
  await page.goto('/')
  await expect(page.getByRole('heading', { name: 'Visão geral' })).toBeVisible()
  const income = page.getByRole('article', { name: 'Renda comprometida' })
  await expect(income.getByText(/14\.014,87/)).toBeVisible()
  await expect(page.getByText('Salário líquido previsto', { exact: true })).toHaveCount(0)
  await expect(page.getByRole('article', { name: 'Teto utilizado' }).getByText('—', { exact: true })).toBeVisible()
  await expect(page.getByRole('region', { name: 'Gastos por categoria' })).toBeVisible()
  await page.getByRole('link', { name: 'Configurações', exact: true }).click()
  await page.getByLabel('Nome do sistema').fill('Minha Moradia')
  await page.getByLabel('Dia de recebimento').fill('5')
  await page.getByLabel('Caixa inicial').fill('1.025,84')
  await page.getByRole('button', { name: 'Salvar configurações' }).click()
  await expect(page.getByText('Configurações salvas.')).toBeVisible()
  await page.getByRole('button', { name: 'Ativar tema escuro' }).click()
  await expect(page.locator('html')).toHaveAttribute('data-theme', 'dark')

  await expect(page.getByRole('heading', { name: 'Créditos', exact: true })).toHaveCount(0)
  const incomeSettings = page.getByRole('region', { name: 'Renda', exact: true })
  await incomeSettings.getByRole('button', { name: 'Agendar reajuste' }).click()
  const future = followingMonth(localMonth())
  await page.getByLabel('Mês de início').fill(future)
  await page.getByLabel('Novo salário líquido').fill('15.321,05')
  await page.getByRole('button', { name: 'Salvar reajuste' }).click()
  await expect(page.getByText('Reajuste salvo.')).toBeVisible()

  await page.reload()
  await expect(page.getByLabel('Nome do sistema')).toHaveValue('Minha Moradia')
  await expect(page.getByLabel('Dia de recebimento')).toHaveValue('5')
  await expect(page.getByLabel('Caixa inicial')).toHaveValue('1.025,84')
  await expect(page.locator('html')).toHaveAttribute('data-theme', 'dark')
  await page.getByRole('link', { name: 'Visão geral', exact: true }).click()
  await expect(income.getByText(/14\.014,87/)).toBeVisible()
  await page.getByLabel('Mês de referência').fill(future)
  await expect(income.getByText(/15\.321,05/)).toBeVisible()
  await expect(page.getByRole('article', { name: 'Saldo do mês' }).getByText(/15\.321,05/)).toBeVisible()
})

test('manages a category on a small screen and restores it after reloading', async ({ page }) => {
  await page.setViewportSize({ width: 390, height: 844 })
  await page.goto('/')
  await page.getByRole('button', { name: 'Abrir menu' }).click()
  await page.getByRole('link', { name: 'Categorias', exact: true }).click()
  await expect(page.getByRole('heading', { name: 'Categorias', level: 1, exact: true })).toBeVisible()

  await page.getByRole('button', { name: 'Adicionar item em Moradia', exact: true }).click()
  await page.getByRole('textbox', { name: 'Nome' }).fill('Reformas')
  await page.getByRole('button', { name: 'Salvar item' }).click()
  await expect(page.getByText('Item criado.')).toBeVisible()
  await page.getByRole('button', { name: 'Editar Reformas' }).click()
  await page.getByRole('textbox', { name: 'Nome' }).fill('Reparos')
  await page.getByRole('button', { name: 'Salvar item' }).click()
  await expect(page.getByText('Reparos', { exact: true })).toBeVisible()

  await page.reload()
  await page.getByRole('searchbox', { name: 'Buscar categorias' }).fill('reparos')
  await page.getByRole('button', { name: 'Desativar Reparos' }).click()
  await page.getByRole('button', { name: 'Desativar', exact: true }).click()
  await expect(page.getByText('Inativo', { exact: true })).toBeVisible()
  await page.getByRole('button', { name: 'Excluir Reparos' }).click()
  await page.getByRole('button', { name: 'Excluir', exact: true }).click()
  await expect(page.getByText('Nenhum item encontrado.')).toBeVisible()
  expect(await page.evaluate(() => document.documentElement.scrollWidth)).toBe(390)
})
